package com.aoo.bcg.common.repair;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DurableRepairCheckpointTest{@Test void checkpointPreservesCursorFailuresReasonsAndRetryState(){var start=new DurableRepairCheckpoint("op","hash","cursor-10",10,Map.of(),Instant.EPOCH);var failed=start.failure("item-11","lock timeout",true,Instant.EPOCH.plusSeconds(1)).failure("item-12","invalid reference",false,Instant.EPOCH.plusSeconds(2));assertEquals("cursor-10",failed.cursor());assertEquals(2,failed.failures().size());assertEquals(List.of("item-11"),failed.retryQueue().stream().map(DurableRepairCheckpoint.Failure::itemId).toList());var retried=failed.failure("item-11","lock timeout",true,Instant.EPOCH.plusSeconds(3));assertEquals(2,retried.failures().get("item-11").attempts());var resumed=retried.success("cursor-11",Instant.EPOCH.plusSeconds(4));assertEquals("cursor-11",resumed.cursor());assertEquals(11,resumed.succeeded());}@Test void exhaustedFailureLeavesRetryQueueAndEntersLedger(){var checkpoint=new DurableRepairCheckpoint("op","hash","0",0,Map.of(),Instant.EPOCH);for(int attempt=1;attempt<=DurableRepairCheckpoint.MAX_RETRY_ATTEMPTS;attempt++)checkpoint=checkpoint.failure("item","timeout",true,Instant.EPOCH.plusSeconds(attempt));assertTrue(checkpoint.retryQueue().isEmpty());assertEquals(1,checkpoint.failureLedger().size());assertEquals(DurableRepairCheckpoint.MAX_RETRY_ATTEMPTS,checkpoint.failureLedger().getFirst().attempts());}}
